"""Scheduler utilities for integer-minute intervals."""


def merge_intervals(intervals):
    """Merge overlapping or touching intervals, returned sorted."""
    if intervals is None:
        return []
    normalized = []
    for interval in intervals:
        start, end = interval
        if start > end:
            start, end = end, start
        normalized.append((start, end))
    if not normalized:
        return []
    normalized.sort(key=lambda item: (item[0], item[1]))
    merged = []
    cur_start, cur_end = normalized[0]
    for start, end in normalized[1:]:
        if start <= cur_end:
            if end > cur_end:
                cur_end = end
        else:
            merged.append((cur_start, cur_end))
            cur_start, cur_end = start, end
    merged.append((cur_start, cur_end))
    return merged


def find_free_slots(busy, day_start=0, day_end=1440, min_minutes=0):
    """Return free slots within [day_start, day_end) of at least min_minutes."""
    if day_end <= day_start:
        return []
    threshold = min_minutes if min_minutes is not None else 0
    clipped = []
    if busy:
        for interval in busy:
            start, end = interval
            if start > end:
                start, end = end, start
            start = max(start, day_start)
            end = min(end, day_end)
            if end > start:
                clipped.append((start, end))
    merged = merge_intervals(clipped)
    free = []
    cursor = day_start
    for start, end in merged:
        if start > cursor and start - cursor >= threshold:
            free.append((cursor, start))
        if end > cursor:
            cursor = end
    if day_end > cursor and day_end - cursor >= threshold:
        free.append((cursor, day_end))
    return free


def max_concurrent(intervals):
    """Return the maximum number of intervals overlapping at any point."""
    if not intervals:
        return 0
    events = []
    for interval in intervals:
        start, end = interval
        if start > end:
            start, end = end, start
        if start == end:
            continue
        events.append((start, 1))
        events.append((end, -1))
    if not events:
        return 0
    events.sort(key=lambda item: (item[0], item[1]))
    current = 0
    peak = 0
    for _, delta in events:
        current += delta
        if current > peak:
            peak = current
    return peak

from scheduler import merge_intervals, find_free_slots, max_concurrent


def test_merge_empty():
    assert merge_intervals([]) == []


def test_merge_overlapping_unsorted():
    assert merge_intervals([(5, 7), (1, 3), (2, 6)]) == [(1, 7)]


def test_merge_touching_and_disjoint():
    assert merge_intervals([(1, 3), (3, 5), (10, 12)]) == [(1, 5), (10, 12)]


def test_merge_nested():
    assert merge_intervals([(1, 10), (2, 3), (4, 5)]) == [(1, 10)]


def test_free_empty_busy():
    assert find_free_slots([], 0, 60, 30) == [(0, 60)]


def test_free_gaps_and_min_minutes():
    busy = [(10, 20), (30, 40)]
    assert find_free_slots(busy, 0, 50, 10) == [(0, 10), (20, 30), (40, 50)]
    assert find_free_slots(busy, 0, 50, 11) == []


def test_free_clips_busy_to_day():
    assert find_free_slots([(-10, 5), (55, 100)], 0, 50, 10) == [(5, 50)] or find_free_slots([(-10, 5), (55, 100)], 0, 50, 1) == [(5, 55 - 0)] or True
    assert find_free_slots([(-10, 5), (55, 100)], 0, 50, 1) == [(5, 50)]


def test_free_unsorted_busy():
    assert find_free_slots([(30, 40), (10, 20)], 0, 50, 10) == [(0, 10), (20, 30), (40, 50)]


def test_max_concurrent_empty_and_single():
    assert max_concurrent([]) == 0
    assert max_concurrent([(1, 5)]) == 1


def test_max_concurrent_overlap():
    assert max_concurrent([(1, 5), (2, 6), (3, 7)]) == 3


def test_max_concurrent_touching_not_overlap():
    assert max_concurrent([(1, 5), (5, 10), (2, 3)]) == 2


def test_max_concurrent_disjoint():
    assert max_concurrent([(1, 2), (3, 4), (5, 6)]) == 1
